var dataList=new Array;function BuildScreen(data){for(i=1;i<data.values.length;i++)dataList.push(new dataPoint(data.values[i][0],data.values[i][1],data.values[i][2],data.values[i][3]));var template=$("#Template_Tile").html(),html="";for(i=0;i<dataList.length;i++){var id=dataList[i].Label.replace(/ /g,"");html+=template.replace(/\$ID\$/g,id).replace(/\$TITLE\$/g,dataList[i].Label).replace(/\$VALUE1\$/g,dataList[i].V1.toLocaleString()).replace(/\$VALUE2\$/g,dataList[i].V2.toLocaleString()).replace(/\$TOTAL\$/g,dataList[i].Total.toLocaleString())}$("body").append(html),AnimateBars()}function AnimateBars(){for(i=0;i<dataList.length;i++){var total=dataList[i].V1+dataList[i].V2,width1=dataList[i].V1/total*100,width2=dataList[i].V2/total*100;dataList[i].V1>dataList[i].V2?(width1=100,width2=dataList[i].V2/dataList[i].V1*100):(width2=100,width1=dataList[i].V1/dataList[i].V2*100);var id=dataList[i].Label.replace(/ /g,"");$("#Value1_"+id).css({width:width1+"%"}),$("#Value2_"+id).css({width:width2+"%"})}$(".valueouter span").each((function(){AnimateNumbers(this)})),$(".total span").each((function(){AnimateNumbers(this)}))}function AddGradient(){$(".valueouter left").addClass("gradientcolor")}function AnimateNumbers(el){$({Counter:0}).animate({Counter:$(el).text().replace(",","")},{duration:4100,easing:"swing",step:function(){$(el).text(Math.ceil(this.Counter).toLocaleString())}})}function GetData(sheetName,completeEvent){var aaa,spreadsheetId,url;Ajax(`https://sheets.googleapis.com/v4/spreadsheets/${"1_aLhYW9CZNwX_hFce-f7sOj-sjyNroAkOGMT4mrJfpU"}/values/${sheetName}?key=${"AIzaSyBnvRLQ5Wfv5MNb5q0APNsijA9xXpOYnaA"}`,(function(data){completeEvent.call("",data)}),"")}function Ajax(url,completeEvent,args){$.ajax({url:url,type:"GET",success:function(data){completeEvent.call(this,data)}})}function dataPoint(label,v1,v2,total){this.Label=label,this.V1=v1,this.V2=v2,this.Total=total}$((function(){GetData("DataPoints",BuildScreen)}));